import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDoubleAll() {
        Assert.assertEquals(listOf(2, 4, 6), transformList(listOf(1, 2, 3), { it * 2 }))
    }

    @Test
    fun testAddOne() {
        Assert.assertEquals(listOf(11, 21), transformList(listOf(10, 20), { it + 1 }))
    }

    @Test
    fun testSquare() {
        Assert.assertEquals(listOf(1, 4, 9, 16), transformList(listOf(1, 2, 3, 4), { it * it }))
    }

    @Test
    fun testEmptyList() {
        Assert.assertEquals(emptyList<Int>(), transformList(emptyList(), { it * 2 }))
    }
}
